import { spawn } from 'node:child_process';
import { dirname, delimiter, resolve } from 'node:path';
import { writeFileSync } from 'node:fs';
const root = resolve(import.meta.dirname, '..');
const node = 'C:/Users/tno/.omp/ai-agent-tools-20261014/runtime/node.exe';
const npm = 'C:/Program Files/nodejs/node_modules/npm/bin/npm-cli.js';
const env = { ...process.env };
const pathKey = Object.keys(env).find(key => key.toLowerCase() === 'path') || 'PATH';
env[pathKey] = dirname(node) + delimiter + (env[pathKey] || '');
const started = Date.now();
const child = spawn(node, [npm, 'run', 'verify'], { cwd: root, env, shell: false, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
let stdout = '', stderr = '', launchError;
child.stdout.on('data', bytes => { stdout += bytes.toString(); process.stdout.write(bytes); });
child.stderr.on('data', bytes => { stderr += bytes.toString(); process.stderr.write(bytes); });
child.on('error', error => { launchError = { code: error.code, message: error.message }; });
child.on('close', (exitCode, signal) => {
  const report = { schemaVersion: 'angit-local-observation/v1', stage: 2, command: 'npm run verify', nodeExecutable: node,
    npmCli: npm, scriptRuntimeSelection: 'Node24 directory prepended to child PATH; npm_node_execpath retained by tooling',
    exitCode, signal, elapsedMs: Date.now() - started, launchError, stdout, stderr,
    limits: ['Private local development acceptance only', 'No real provider/service/integration/restore/release', 'Installed consumer uses owner-private fixture seam, not default-host ACL certification'] };
  writeFileSync(resolve(root, 'evidence/stage2-verification.json'), JSON.stringify(report, null, 2) + '\n');
  process.exitCode = exitCode === 0 && !signal && !launchError ? 0 : 1;
});

